Scene cc0_scene(const char*name,bool posed){
 Scene scene;scene.active().visible=false;const auto group=append_humanoid(scene,humanoid_baseline_defaults(name),"Actual CC0 normal source",{},64);
 if(posed)for(const auto&item:scene.objects())if(item.group==group&&item.deformation){auto d=*item.deformation;if(d.skeleton){d.pose.clear();for(const auto&b:d.skeleton->bones)d.pose.push_back(b.rest);if(d.humanoid&&d.humanoid->joints.contains("hips"))d.pose[d.humanoid->joints.at("hips")].scale={1.15f,.9f,.7f};if(d.humanoid&&d.humanoid->joints.contains("spine")){auto&p=d.pose[d.humanoid->joints.at("spine")];p.scale={.85f,1.05f,1.2f};p.rotation={std::cos(.08f),0,0,std::sin(.08f)};}}if(d.morphs){d.morph_weights.assign(d.morphs->targets.size(),0);if(!d.morph_weights.empty())d.morph_weights[0]=.35f;}scene.set_deformation(item.id,std::move(d));}
 scene.validate();return scene;
}
