std::shared_ptr<SourceMaterialBindings> ordinary_binding(const SculptObject&o){
 if(!o.material_bindings)return {};const auto&src=*o.material_bindings;auto out=std::make_shared<SourceMaterialBindings>();out->has_mtoon=src.has_mtoon;out->material=src.material;out->roles=src.roles;out->native_reference=src.native_reference;out->physical_emission=src.physical_emission;out->material.textures[size_t(MToonSlot::Normal)].index=-1;out->material.parameters.normal_enabled=false;out->roles[size_t(MToonSlot::Normal)]={};out->validate();return out;
}
