 result->mesh.positions={center+axis_x*(-span)+axis_y*(-span),center+axis_x*span+axis_y*(-span),center+axis_x*span+axis_y*span,center+axis_x*(-span)+axis_y*span};result->mesh.normals.assign(4,desired);result->mesh.uv.assign(4,oracle.coordinate(tri,bary,0,true));
