Mat4 face_projection(Vec3 center,Vec3 x,Vec3 y,Vec3 n,float span){Mat4 result{};for(size_t k=0;k<3;++k){const std::array<float,3>a{x.x,x.y,x.z},b{y.x,y.y,y.z},c{n.x,n.y,n.z};result[k*4]=a[k]/span;result[k*4+1]=b[k]/span;result[k*4+2]=c[k]/2;}result[12]=-dot(x,center)/span;result[13]=-dot(y,center)/span;result[14]=-dot(n,center)/2;result[15]=1;return result;}
Pixels draw_view(SurfaceRenderer&r,std::shared_ptr<const MeshSnapshot>s,const Mat4&matrix,Vec3 camera){r.draw(std::move(s),{},matrix,{camera.x,camera.y,camera.z},Fbo::size,Fbo::size,true);return read();}
void tune(Scene&scene,uint64_t id){auto&o=scene.object(id);const float gray=srgb_to_linear(136.f/255);o.material.color={gray,gray,gray,1};o.material.alpha=Material::AlphaMode::Opaque;o.material.unlit=false;o.material.metallic=0;o.material.roughness=1;if(o.material_bindings&&o.material_bindings->has_mtoon){auto binding=std::make_shared<SourceMaterialBindings>(*o.material_bindings);binding->material.parameters.base_color=o.material.color;binding->material.parameters.shade_color={gray*.25f,gray*.3f,gray*.35f};binding->material.parameters.toony=0;binding->validate();o.material_bindings=std::move(binding);}}
